DO $test$ DECLARE a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();BEGIN
 INSERT INTO auth.users(id) VALUES(a),(b),(c),(d);
 INSERT INTO public.profiles(user_id,account_state) VALUES(a,'active'),(b,'active'),(c,'active'),(d,'active');
 INSERT INTO public.user_privacy_settings(user_id,profile_visibility,contact_permission) SELECT v.id,'friends','members' FROM (VALUES(a),(b),(c),(d)) v(id);
 INSERT INTO public.user_eligibility(user_id,status,verification_method,verification_version,verified_at) SELECT v.id,'eligible','test','test',now() FROM (VALUES(a),(b),(c),(d)) v(id);
 INSERT INTO public.policy_acceptances(user_id,policy_version_id) SELECT v.id,p.id FROM (VALUES(a),(b),(c),(d)) v(id) CROSS JOIN public.policy_versions p WHERE p.mandatory AND p.published_at<=now() AND p.retired_at IS NULL;
 INSERT INTO public.friendships(user_low,user_high) VALUES(least(a,b),greatest(a,b)),(least(a,c),greatest(a,c));
 PERFORM set_config('test.safe_a',a::text,false);PERFORM set_config('test.safe_b',b::text,false);PERFORM set_config('test.safe_c',c::text,false);PERFORM set_config('test.safe_d',d::text,false);
 IF has_function_privilege('anon','public.list_own_blocked_received_messages(timestamptz,uuid)','EXECUTE') OR has_table_privilege('authenticated','public.messages','SELECT') THEN RAISE EXCEPTION 'Unexpected direct access';END IF;
END $test$;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',current_setting('test.safe_a'),false);
SELECT set_config('test.safe_ab',public.start_friend_conversation(current_setting('test.safe_b')::uuid)::text,false);
SELECT set_config('test.safe_ac',public.start_friend_conversation(current_setting('test.safe_c')::uuid)::text,false);
SELECT public.send_friend_message(current_setting('test.safe_ab')::uuid,'Outgoing must not appear');
SELECT set_config('request.jwt.claim.sub',current_setting('test.safe_b'),false);
SELECT set_config('test.safe_msg',public.send_friend_message(current_setting('test.safe_ab')::uuid,'Received before block')::text,false);
SELECT set_config('request.jwt.claim.sub',current_setting('test.safe_c'),false);
SELECT public.send_friend_message(current_setting('test.safe_ac')::uuid,'From unblocked sender');
SELECT set_config('request.jwt.claim.sub',current_setting('test.safe_a'),false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_blocked_received_messages()) THEN RAISE EXCEPTION 'Unblocked message exposed';END IF;END $test$;
SELECT public.block_user(current_setting('test.safe_b')::uuid);
DO $test$ BEGIN
 IF (SELECT count(*) FROM public.list_own_blocked_received_messages())<>1 OR NOT EXISTS(SELECT 1 FROM public.list_own_blocked_received_messages() WHERE id=current_setting('test.safe_msg')::uuid AND body='Received before block') THEN RAISE EXCEPTION 'Wrong safety results';END IF;
 BEGIN PERFORM * FROM public.list_friend_messages(current_setting('test.safe_ab')::uuid);RAISE EXCEPTION 'Blocked thread reopened';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.send_friend_message(current_setting('test.safe_ab')::uuid,'No');RAISE EXCEPTION 'Blocked send allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM * FROM public.list_own_blocked_received_messages(now(),null);RAISE EXCEPTION 'Bad cursor';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
END $test$;
SELECT set_config('test.safe_report',public.report_received_friend_message(current_setting('test.safe_msg')::uuid,'Concern after block')::text,false);
SELECT set_config('request.jwt.claim.sub',current_setting('test.safe_b'),false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_blocked_received_messages()) THEN RAISE EXCEPTION 'Blocked sender saw blocker messages';END IF;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.safe_d'),false);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_blocked_received_messages()) THEN RAISE EXCEPTION 'Nonparticipant saw messages';END IF;END $test$;
SELECT set_config('request.jwt.claim.sub',current_setting('test.safe_a'),false);
SELECT public.unblock_user(current_setting('test.safe_b')::uuid);
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM public.list_own_blocked_received_messages()) THEN RAISE EXCEPTION 'Notice remains after unblock';END IF;END $test$;
RESET ROLE;
UPDATE public.profiles SET account_state='suspended' WHERE user_id=current_setting('test.safe_a')::uuid;
SET ROLE authenticated;
DO $test$ BEGIN BEGIN PERFORM * FROM public.list_own_blocked_received_messages();RAISE EXCEPTION 'Suspended access';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $test$;
RESET ROLE;
